insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('a69cf2b2-aff4-5b6d-af90-195591bf1a4a', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '14270a41-7c88-5f81-ae15-86701b7aff46', 'd37cec50-e171-5815-a1b1-e8250d4a2fa1', 'Which describes a public good?', '["Rival and excludable in use","Provided only by private firms","Non-excludable and non-rival","Always a type of merit good"]'::jsonb, 'Non-excludability causes the free rider problem, so markets fail to provide it.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
