insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('b814fb04-b1e0-5b94-ad2b-ffd70b87efe0', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '2e481239-978a-5127-ae80-1b8e801f6f72', '95ba1fdc-7967-54ec-af65-86aa1282a718', 'Which causes a rightward shift of the demand curve for a normal good?', '["A rise in the price of a complement","A rise in consumer incomes","A fall in the good''s own price","A fall in the price of a substitute"]'::jsonb, 'Higher income raises demand at every price for a normal good. An own-price change is a movement along the curve.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
