insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('49af13e5-6009-5975-a4c7-183684554348', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '2e481239-978a-5127-ae80-1b8e801f6f72', '95ba1fdc-7967-54ec-af65-86aa1282a718', 'If demand is price inelastic, what will a price rise do?', '["Reduce demand to zero","Decrease total revenue","Leave revenue unchanged","Increase total revenue"]'::jsonb, 'The % fall in quantity is smaller than the % rise in price, so revenue rises.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
