insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f6e5f743-4c62-5a47-aeb3-4c0fc4cb6dc0', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '2e481239-978a-5127-ae80-1b8e801f6f72', '95ba1fdc-7967-54ec-af65-86aa1282a718', 'Other things equal, what will a rise in the cost of raw materials do?', '["Raise both equilibrium price and equilibrium quantity","Lower both equilibrium price and equilibrium quantity","Raise equilibrium price and lower equilibrium quantity","Lower equilibrium price and raise equilibrium quantity"]'::jsonb, 'Supply shifts left: price rises and quantity falls.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
