insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('f7f72808-1f61-5343-a73d-aa2ec46a85a6', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '2e481239-978a-5127-ae80-1b8e801f6f72', '95ba1fdc-7967-54ec-af65-86aa1282a718', 'What is consumer surplus?', '["The extra profit firms earn above their normal profit","The price of a good minus its cost of production","The tax revenue that the government collects on a good","What consumers are willing to pay minus what they pay"]'::jsonb, 'It is the area below the demand curve and above the price.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
