insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('0001c288-b0b4-5e9e-a451-f942ed2faf8b', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '176d8144-7473-57dc-ab8a-56a00e12efcd', '5fa3e3f1-859d-558a-a099-f6a8a8a3b1b6', 'How does a specific indirect tax shift the supply curve?', '["Up (left) by the amount of the tax, parallel","Up (left), pivoting from where it meets the axis","It does not shift the supply curve at all","Down (right) by the amount of the tax, parallel"]'::jsonb, 'A specific tax is a fixed amount per unit, so supply shifts up parallel.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
