insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('393c8b0d-d220-58da-aca3-b0de76bfffb1', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '176d8144-7473-57dc-ab8a-56a00e12efcd', '5fa3e3f1-859d-558a-a099-f6a8a8a3b1b6', 'Which is a reason governments subsidise public transport?', '["It creates positive externalities, such as less congestion","It reduces consumer surplus for people who drive cars","It creates a surplus of buses that can be sold abroad","It is a demerit good, so people use it too little"]'::jsonb, 'Subsidies increase consumption of goods with external benefits.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
