insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('c06253bd-9218-57df-a578-28acd994d5b8', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '176d8144-7473-57dc-ab8a-56a00e12efcd', '5fa3e3f1-859d-558a-a099-f6a8a8a3b1b6', 'What is a progressive tax?', '["The share of income paid in tax rises as income rises","Everyone pays the same amount of tax, whatever they earn","A tax that is only charged on spending, not on income","People on low incomes pay a higher share of their income"]'::jsonb, 'Progressive taxes reduce income inequality.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
