insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('bd05bfa9-ff7d-5b20-a686-ab46f8e8940c', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '176d8144-7473-57dc-ab8a-56a00e12efcd', '5fa3e3f1-859d-558a-a099-f6a8a8a3b1b6', 'For which goods is direct provision by the government most likely?', '["Public goods such as national defence","Luxury goods such as expensive cars","Fast food sold by restaurant chains","Mobile phones and other electronics"]'::jsonb, 'Markets fail to provide public goods because of the free rider problem.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
