insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('6fc609a2-184f-56c0-a796-b5a8fc113421', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '10920fe3-a075-55af-a5c0-23c89a2fa8af', 'ec6091d8-febc-5454-a589-59f88e8b52f3', 'What does GDP measure?', '["The total value of output produced within a country in a year","The total amount the government spends in one year","The total amount of money circulating in the economy","The total output of a country''s citizens around the world"]'::jsonb, 'GDP measures output produced within the country''s borders.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
