insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('cedc2eb6-6f2f-587a-ad4d-2dcec39b614d', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '10920fe3-a075-55af-a5c0-23c89a2fa8af', 'ec6091d8-febc-5454-a589-59f88e8b52f3', 'What does a fall in the price level lead to?', '["A shift of the AS curve to the left","A movement down along the AD curve","A shift of the AD curve to the left","A shift of the AD curve to the right"]'::jsonb, 'A price-level change moves along AD; other factors shift it.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
