insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('a2e3ecab-07d2-5dd0-aeae-0714c85e10ea', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '10920fe3-a075-55af-a5c0-23c89a2fa8af', 'ec6091d8-febc-5454-a589-59f88e8b52f3', 'Which is a cause of a rightward shift in long-run aggregate supply?', '["A fall in the value of the country''s exports","A rise in interest rates set by the bank","Higher indirect taxes on goods and services","Improvements in education and technology"]'::jsonb, 'LRAS shifts when productive capacity grows.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
