insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('e6952eed-afba-5158-a13c-af9241fbd0c5', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '10920fe3-a075-55af-a5c0-23c89a2fa8af', 'ec6091d8-febc-5454-a589-59f88e8b52f3', 'When does frictional unemployment occur?', '["When workers are between jobs","When an industry declines for good","When demand falls in a recession","When jobs depend on the season"]'::jsonb, 'It is short-term and caused by time spent searching for a new job.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
