insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('6404df07-5171-5959-a686-17102bfca4d2', 'ed876f60-9f86-5aa2-a19b-b7e4b20d1204', '10920fe3-a075-55af-a5c0-23c89a2fa8af', 'ec6091d8-febc-5454-a589-59f88e8b52f3', 'What causes cost-push inflation?', '["Exports rising faster than imports each year","Interest rates falling, so borrowing increases","Aggregate demand rising faster than output","Rising costs of production, such as wages or oil"]'::jsonb, 'Higher costs shift SRAS left, raising the price level.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
