insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('53346d5d-9a7e-5b3b-ae0c-26c1eb061ec8', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '09386744-96be-5bf2-a548-99dc5b7e213d', 'c3ca14b2-c088-53c3-acd9-29ee77afb8e7', 'Which is an example of vertical integration?', '["A car maker buying a tyre manufacturer","A bakery buying a shoe shop","Two banks merging","A supermarket buying another supermarket"]'::jsonb, 'It merges firms at different stages of the same production chain.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
