insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('73d5b61b-2bd8-5c68-a117-62aae8945751', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '09386744-96be-5bf2-a548-99dc5b7e213d', 'c3ca14b2-c088-53c3-acd9-29ee77afb8e7', 'Where will a firm aiming to maximise sales revenue produce?', '["MR = 0","MC = MR","AC = AR","P = MC"]'::jsonb, 'Total revenue is at its peak when marginal revenue is zero.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
