insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('564dce9d-ed3b-56c2-a9ed-df8d151159d5', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '316a086c-c5b7-592b-a0b5-2e222099f78f', '3ba5405e-0378-570d-ae70-80ff5f5d60e3', 'What is a Pigouvian tax designed to do?', '["Pay for subsidies on merit goods","Reduce inflation in the economy","Raise revenue from the richest people","Make polluters pay the external cost"]'::jsonb, 'Setting the tax equal to the external cost moves output to the social optimum.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
