insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('ed7ea0f5-624f-5393-a592-8b8f0e195cb2', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '316a086c-c5b7-592b-a0b5-2e222099f78f', '3ba5405e-0378-570d-ae70-80ff5f5d60e3', 'How do tradable pollution permits work?', '["Total pollution is capped and firms trade allowances","Polluting firms are subsidised to buy new machines","All pollution is banned and firms are fined for it","A minimum price is set for goods that cause pollution"]'::jsonb, 'Firms that can cut pollution cheaply sell permits to those that can''t.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
