insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('a3fe3d86-23fc-5d49-a425-64bfdd3e43d3', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '316a086c-c5b7-592b-a0b5-2e222099f78f', '3ba5405e-0378-570d-ae70-80ff5f5d60e3', 'What is the marginal revenue product of labour?', '["The extra revenue from employing one more worker","The cost of training one more worker for the job","The total output divided by the number of workers","The wage rate paid to each worker in the market"]'::jsonb, 'MRP = marginal product × marginal revenue.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
