insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('6334fa22-bb1b-52ed-a50f-3d0e329375e9', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '316a086c-c5b7-592b-a0b5-2e222099f78f', '3ba5405e-0378-570d-ae70-80ff5f5d60e3', 'What will a monopsony employer in the labour market tend to do?', '["Pay the same wage but employ more workers than a competitive market","Pay lower wages and employ fewer workers than a competitive market","Pay higher wages and employ more workers than a competitive market","Pay higher wages but employ fewer workers than a competitive market"]'::jsonb, 'As the only buyer, it can push wages down.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
