insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('65415fb8-691b-5241-ac30-ab838ba9d0b8', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '316a086c-c5b7-592b-a0b5-2e222099f78f', '3ba5405e-0378-570d-ae70-80ff5f5d60e3', 'When can a trade union raise wages without reducing employment?', '["When the market is perfectly competitive","When the employer is a monopsony","When demand for labour is very elastic","When workers can easily be replaced"]'::jsonb, 'In monopsony a union can move wages and employment towards the competitive level.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
