insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('368f8f6e-bc32-5abf-a09e-066aeff1e20f', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '316a086c-c5b7-592b-a0b5-2e222099f78f', '3ba5405e-0378-570d-ae70-80ff5f5d60e3', 'What are transfer earnings?', '["Benefits paid by the government to workers on low pay","The minimum payment needed to keep a factor in its current use","The tax that a worker pays on the income they earn","Any earnings above the minimum needed to keep a factor in use"]'::jsonb, 'Anything above transfer earnings is economic rent.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
