insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('5fe7a9ec-6bd0-5344-ab4b-35519cec11a1', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '316a086c-c5b7-592b-a0b5-2e222099f78f', '3ba5405e-0378-570d-ae70-80ff5f5d60e3', 'When does government failure occur?', '["When the government''s budget is exactly balanced","When the government makes taxes more progressive","When intervention leads to a less efficient outcome","When markets fail to provide public goods at all"]'::jsonb, 'Causes include poor information, unintended effects and administrative costs.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
