insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('50ae13a0-b88d-560b-aede-c063ea758d35', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '316a086c-c5b7-592b-a0b5-2e222099f78f', '3ba5405e-0378-570d-ae70-80ff5f5d60e3', 'What is a poverty trap?', '["Unemployment is so high that people cannot find any work","Everyone pays the same rate of tax, whatever their income","Earning more means losing benefits, so little extra income is gained","Prices rise faster than wages, so real incomes fall each year"]'::jsonb, 'High effective marginal tax rates reduce the incentive to work.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
