insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('64d48a09-537e-5b10-af78-a70cf9815f09', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'a0ba86d1-b5f5-56bf-acc7-0e9e6e5e5fa9', 'b9870d47-0e4b-5bce-a8fb-b04188ed4f57', 'What does the accelerator theory link investment to?', '["The exchange rate of the currency","The rate of change of national income","The amount the government borrows","The level of interest rates on its own"]'::jsonb, 'Firms invest more when demand is growing faster.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
