insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('67dc19b9-bbba-57d2-a9db-afad277768ba', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'a0ba86d1-b5f5-56bf-acc7-0e9e6e5e5fa9', 'b9870d47-0e4b-5bce-a8fb-b04188ed4f57', 'Which is a limitation of using GDP to compare living standards?', '["It is measured in money rather than in goods","It ignores the informal economy and inequality","It includes the output of every firm in the economy","It is adjusted for inflation, so it can''t be compared"]'::jsonb, 'GDP can mislead about real well-being.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
