insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('e3ad958e-5370-58b6-a8b0-a45aee5b8115', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'a0ba86d1-b5f5-56bf-acc7-0e9e6e5e5fa9', 'b9870d47-0e4b-5bce-a8fb-b04188ed4f57', 'What does broad money include?', '["Only the notes and coins in use","Only the reserves held by banks","Bonds issued by the government","Notes, coins and bank deposits"]'::jsonb, 'Broad money adds bank deposits to narrow money.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
