insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('99940a8d-3940-5243-a1a0-c684ef722f6c', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'a0ba86d1-b5f5-56bf-acc7-0e9e6e5e5fa9', 'b9870d47-0e4b-5bce-a8fb-b04188ed4f57', 'Which equation is the quantity theory of money?', '["Y = C + S","AD = C + I + G + (X − M)","MV = PT","P = MC"]'::jsonb, 'Monetarists argue increases in M cause rises in P if V and T are stable.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
