insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('0ed33f32-5516-53b9-aab1-994896762fbf', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'a0ba86d1-b5f5-56bf-acc7-0e9e6e5e5fa9', 'b9870d47-0e4b-5bce-a8fb-b04188ed4f57', 'According to Keynes'' liquidity preference theory, what does the demand for money depend on?', '["The supply of government bonds and their interest rate","Transactions, precautionary and speculative motives","The rate of inflation and the level of unemployment","The value of exports, imports and the exchange rate"]'::jsonb, 'Speculative demand is inversely related to interest rates.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
