insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('7c2804d9-cd3b-5674-abe6-8580adb3e2a6', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '030e5a8c-5d6f-5737-a4f0-b5848bf7b506', 'abd39cf9-4802-532a-a50b-a6a5ca2632fc', 'What do monetarists believe happens in the long run?', '["Fiscal policy always reduces unemployment","Unemployment returns to the natural rate","AD has a permanent effect on real output","Inflation does not matter to the economy"]'::jsonb, 'The long-run Phillips curve is vertical at the natural rate.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
