insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('332914f3-1d80-55d2-a17e-3d56e6bde5b7', '37741ac7-a6d3-5a19-a564-e012eb241ddb', '030e5a8c-5d6f-5737-a4f0-b5848bf7b506', 'abd39cf9-4802-532a-a50b-a6a5ca2632fc', 'Which is a possible consequence of a large budget deficit?', '["A current account surplus with other countries","Lower government borrowing in future years","Falling interest rates across the economy","Rising national debt and interest payments"]'::jsonb, 'Deficits must be financed by borrowing.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
