insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('52ccaafb-9319-5f0d-aebb-64d7ce6244bd', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'ba73d79a-7533-5601-a57e-3fd6b411010f', 'a4d31b37-7982-52bb-a6fe-ccc4786116bd', 'Which is a typical characteristic of a developing economy?', '["A large tertiary sector with many services","A high Human Development Index score","A large share of jobs in the primary sector","A low rate of population growth each year"]'::jsonb, 'Many developing countries rely heavily on agriculture and raw materials.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
