insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('17443ce1-e64f-55a5-a2d9-85b1844cb28f', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'ba73d79a-7533-5601-a57e-3fd6b411010f', 'a4d31b37-7982-52bb-a6fe-ccc4786116bd', 'What is foreign direct investment?', '["A person buying foreign currency for a holiday","A firm investing in production facilities abroad","A business importing goods from another country","A government giving aid to another country"]'::jsonb, 'FDI involves ownership and control of assets in another country.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
