insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('4d35a211-ced5-503a-a7f3-e29b51b65c39', '37741ac7-a6d3-5a19-a564-e012eb241ddb', 'ba73d79a-7533-5601-a57e-3fd6b411010f', 'a4d31b37-7982-52bb-a6fe-ccc4786116bd', 'Which is a criticism of globalisation?', '["It increases the competition that domestic firms face","It spreads new technology between different countries","It always lowers the prices consumers pay for goods","It can increase inequality and exploit low-wage workers"]'::jsonb, 'Gains are not always evenly shared.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
