insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('3b0a5540-d898-5f6f-a5c6-df6d6fb6e961', '20503b30-2347-51fd-a078-27b8850c6557', '36f589e5-f924-501d-a645-dee9602ffde7', '522412a1-95b7-50ac-abc6-2019d98ff63a', 'What does a social enterprise aim to do?', '["Be owned and run by the government for the public","Avoid paying tax by giving its profits away to charity","Maximise profit for its owners and nobody else","Achieve social or environmental aims as well as financial ones"]'::jsonb, 'Social enterprises have a triple bottom line: profit, people, planet.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
