insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('301585b1-564c-5f77-a2fb-6362e7621995', '20503b30-2347-51fd-a078-27b8850c6557', '36f589e5-f924-501d-a645-dee9602ffde7', '522412a1-95b7-50ac-abc6-2019d98ff63a', 'What does corporate social responsibility (CSR) mean?', '["A business paying the lowest wages that the law allows","A business following only the wishes of its shareholders","A business considering its impact on society and the environment","A business finding legal ways to avoid paying its taxes"]'::jsonb, 'CSR goes beyond legal obligations.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
