insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('313d916f-8be0-5ee5-ad99-6646b7def17d', '20503b30-2347-51fd-a078-27b8850c6557', '78b4ff45-3c8b-5ab9-a211-85d6a19ffb27', 'de803b5c-149c-5681-a6fc-6a038a721265', 'What does a price elasticity of demand of −0.4 mean?', '["Demand is price elastic","Demand is perfectly elastic","Demand is price inelastic","Demand is unitary"]'::jsonb, 'Quantity changes by less than the price change in percentage terms.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation;
