insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('ae423d79-4110-508b-a5a5-c3cbe351d689', '20503b30-2347-51fd-a078-27b8850c6557', '661dad7d-d6d9-56cf-a0eb-62a7efd18a73', 'b7c20e1b-1fb4-5132-a71d-c10157724b1f', 'What does just-in-time inventory management aim to do?', '["Avoid long-term relationships with any of its suppliers","Buy materials in bulk to get the biggest discounts","Hold large buffer stocks in case demand suddenly rises","Hold minimal stock, with supplies arriving only when needed"]'::jsonb, 'JIT cuts storage costs but depends on reliable suppliers.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
