insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('7c14f90c-9e18-5107-a6cb-1a3157ae9479', '20503b30-2347-51fd-a078-27b8850c6557', '661dad7d-d6d9-56cf-a0eb-62a7efd18a73', 'b7c20e1b-1fb4-5132-a71d-c10157724b1f', 'What does outsourcing mean?', '["Selling part of the business to a rival","Hiring more employees to carry out a function","Using another business to carry out a function","Making every part and service in-house"]'::jsonb, 'It can reduce costs but loses some control over quality.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
