insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('0b0d4e76-e5d9-5ed8-abf4-bdc784c71886', '04b61e71-47e0-5a22-a027-969557678533', '16d13ffb-73e8-5d37-a33d-6d4155fc7631', 'baf1af63-50fd-5079-ab48-4a8870937d78', 'Which is an example of a legal influence on business?', '["New technology in production","Rising incomes of consumers","Changing fashions and tastes","Consumer protection laws"]'::jsonb, 'Laws set rules businesses must follow.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
