insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('322bad9d-49a4-556b-a019-bb25b0d43134', '04b61e71-47e0-5a22-a027-969557678533', '91c8dd69-77c7-57ff-aa92-288fada94def', '3e162348-5ce9-581a-a3a3-770146247775', 'According to Goleman, what does an emotionally intelligent leader have?', '["Strong technical skills only","Strong autocratic control","Strong self-awareness and empathy","Strong financial knowledge"]'::jsonb, 'Goleman''s five elements include self-awareness, self-regulation, motivation, empathy and social skills.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
