insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('756cd6cd-b620-5f6a-a9d4-cca7c154b96f', '04b61e71-47e0-5a22-a027-969557678533', '91c8dd69-77c7-57ff-aa92-288fada94def', '3e162348-5ce9-581a-a3a3-770146247775', 'What does collective bargaining involve?', '["Each worker agreeing their own pay deal alone","Workers setting their own pay without managers","Negotiation between employers and trade unions","The government setting wages for every job"]'::jsonb, 'Unions negotiate for many workers together.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
