insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('be996473-645d-5234-ae80-4e86aaea14e2', '04b61e71-47e0-5a22-a027-969557678533', '91c8dd69-77c7-57ff-aa92-288fada94def', '3e162348-5ce9-581a-a3a3-770146247775', 'When does labour productivity increase?', '["When the wages paid to each worker rise","When the rate of absenteeism among staff rises","When more workers produce the same amount of output","When output rises and the workforce stays the same"]'::jsonb, 'Productivity = output ÷ workers.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
