insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('8cfa1ea1-7b40-587b-ab78-d15591145c86', '04b61e71-47e0-5a22-a027-969557678533', '12f9dd98-012f-5b0e-a17e-9e8d93e875d3', 'c427c2d4-2d6d-5ead-a625-79a9ad547cd6', 'In critical path analysis, what is the critical path?', '["The sequence of activities with zero float","The activities that can be delayed safely","The cheapest route through the whole project","The route through the network with most float"]'::jsonb, 'Any delay on the critical path delays the whole project.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
