insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('87ced9b0-086b-52a0-a55f-ea96003df709', '04b61e71-47e0-5a22-a027-969557678533', '12f9dd98-012f-5b0e-a17e-9e8d93e875d3', 'c427c2d4-2d6d-5ead-a625-79a9ad547cd6', 'How is total float calculated?', '["Latest start − earliest finish − duration","Duration − latest finish + earliest start","Earliest start + duration − latest finish","Latest finish − duration − earliest start"]'::jsonb, 'It shows how long an activity can be delayed without delaying the project.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
