insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('7e53ea54-21f6-5fca-af71-3ec6b40e115f', '103f700e-8c69-5619-a982-5a2b4a8aeca9', '7148887c-4456-5a2c-a407-523f31481bf9', 'd5936fae-83c3-51b6-ad07-57f353b12153', 'What is CSMA/CD used for?', '["Encrypting data before it is sent across the network","Assigning IP addresses to devices when they connect","Detecting and handling collisions on a shared medium","Compressing frames so that more data fits on the link"]'::jsonb, 'Devices wait a random time and retransmit after a collision.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
