insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('cc6289d9-6f4d-5e05-a5d4-1f3c3850b5ed', '00d139c6-357b-5ca0-ab19-e2369aebe747', '65a56281-9deb-5f5b-ac26-255c32357f12', 'fcb85bae-5281-5f3b-aea6-56dfce64f647', 'Which statement describes packet switching?', '["Packets may take different routes and are reassembled at the end","All the data is sent in one piece along the fastest route","Packets have no headers, so they must arrive in order","A dedicated path is reserved for the whole of the communication"]'::jsonb, 'This uses the network efficiently.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
