insert into questions (id, course_id, chapter_id, quiz_id, prompt, options, explanation) values ('3b77f55e-d02d-5529-a085-43555d4a7226', '00d139c6-357b-5ca0-ab19-e2369aebe747', '65a56281-9deb-5f5b-ac26-255c32357f12', 'fcb85bae-5281-5f3b-aea6-56dfce64f647', 'What is an advantage of circuit switching?', '["Packets can be rerouted if a link breaks","Data arrives in order over a constant connection","No path has to be set up before data is sent","Bandwidth is shared efficiently between users"]'::jsonb, 'The dedicated path suits live voice calls.') on conflict (id) do update set prompt = excluded.prompt, explanation = excluded.explanation, options = excluded.options;
